R, C = M['R'], M['C']
SC = {"متحفظ": run(dict(vol_mult=.8, fee_mult=.92, opex_mult=1.05)), "أساسي": M, "متفائل": run(dict(vol_mult=1.1, fee_mult=1.05, opex_mult=.98))}


def s_strategy():
    o = sec(8, "الدراسات الاستراتيجية", "يجمع هذا القسم أدوات التحليل الاستراتيجي التي تحدد أين يتنافس المكتب وبماذا يتميز وما الذي يحمي أرباحه على المدى الطويل.")
    o += h2("التحليل الرباعي (SWOT)")
    o += grid([
        card("نقاط القوة", ul(["نموذج أتعاب شفاف يفصل التصميم عن هامش التنفيذ", "موقع في مركز 47% من مبيعات المطورين", "هيكل تكاليف خفيف في البداية وتعيين مرتبط بالعقود", "لا يحمل مخاطر مخزون ولا تمويل أعمال المقاولين", "تجربة عرض بالواقع الافتراضي ومكتبة خامات فعلية"]), "s"),
        card("نقاط الضعف", ul(["علامة جديدة دون معرض أعمال منفذة", "اعتماد مرتفع على المدير الإبداعي في السنتين الأوليين", "سنة أولى خاسرة تشغيلياً", "هامش أمان نقدي محدود إذا تأخر اكتساب العملاء", "صعوبة حماية الأفكار التصميمية من التقليد"]), "w"),
        card("الفرص", ul(["دخول مبيعات 2022 إلى 2025 مرحلة التسليم", "الوحدات تُسلَّم نصف تشطيب في الغالب", "فجوة جودة تقارب 30% من الطلب المتخصص", "طلب المصريين بالخارج على إدارة كاملة عن بعد", "اتفاقات مع المطورين والوسطاء لتحويل العملاء", "تصدير خدمات التصميم لأسواق الخليج بالعملة الصعبة"]), "o"),
        card("التهديدات", ul(["فائدة 20% إلى 21% ترفع تكلفة التمويل وتؤجل قرارات التشطيب", "تضخم الرواتب واستقطاب الكفاءات إلى الخليج", "تراجع عدد الوحدات المباعة 3% في 2026", "أدوات الذكاء الاصطناعي تضغط على أسعار التصميم الأولي", "اتجاه بعض المطورين للتسليم كامل التشطيب"]), "t"),
    ], 2)
    o += h2("مصفوفة الاستراتيجيات المشتقة (TOWS)")
    o += table(["", "الفرص", "التهديدات"], [
        ["<b>نقاط القوة</b>", "استراتيجيات هجومية: باقة إدارة كاملة عن بعد للمصريين بالخارج بتقارير مصورة أسبوعية. اتفاقات تحويل مع ثلاثة مطورين ووسطاء في شرق القاهرة.", "استراتيجيات دفاعية: تثبيت الأتعاب للمتر عند التعاقد لطمأنة العميل في بيئة تضخمية. توظيف أدوات الذكاء الاصطناعي داخلياً لخفض ساعات التصميم الأولي بدل منافستها."],
        ["<b>نقاط الضعف</b>", "استراتيجيات علاجية: تنفيذ ثلاثة مشروعات نموذجية بسعر تعريفي في الربع الأول لبناء معرض أعمال مصور. نظام توثيق يقلل الاعتماد على شخص واحد.", "استراتيجيات تجنب: احتياطي سيولة ستة أشهر وتسهيل ائتماني غير مسحوب. عدم التعيين قبل توقيع عقود تغطي 70% من طاقة الموظف الجديد."],
    ], "مصفوفة TOWS", widths=[14, 43, 43])
    o += h2("تحليل الخندق الاقتصادي (Moat)")
    o += p("الخندق الاقتصادي هو ما يمنع المنافسين من تآكل أرباح الشركة بمرور الوقت. قيّمنا مصادر الخندق الخمسة المتعارف عليها على مقياس من صفر إلى خمسة، عند التأسيس وبعد خمس سنوات إذا نُفذت الخطة.")
    moat = [("العلامة والسمعة (أصول غير ملموسة)", 1, 3.5), ("تكلفة التحول لدى العميل", 2.5, 3), ("أثر الشبكة (إحالات العملاء والمطورين)", .5, 2.5), ("ميزة التكلفة والكفاءة التشغيلية", 1.5, 3), ("الحجم الكفء في السوق المحلية", 1, 2)]
    o += fig(bars([m[0].split(" (")[0] for m in moat], [("عند التأسيس", [m[1] for m in moat]), ("السنة الخامسة (مستهدف)", [m[2] for m in moat])], unit="الدرجة من 5", ymax=5, h=250, legend_gap=110), "تقييم مصادر الخندق الاقتصادي للمشروع", "تقييم فريق الدراسة")
    o += callout("قراءة صريحة للخندق", "الخندق عند التأسيس ضيق، ومتوسط درجاته 1.3 من 5. هذه طبيعة النشاط الخدمي المهني وليست عيباً خاصاً بالمشروع. الخندق يُبنى بالتراكم: كل مشروع منفذ وموثق يضيف إلى السمعة ويولد إحالات. لذلك تعتمد قيمة المشروع على استمراره بعد السنة الخامسة، وهو ما تؤكده الأرقام المالية حيث تأتي معظم القيمة الحالية من القيمة الاستمرارية.", "cop")
    o += h2("مصفوفة أنسوف لمسارات النمو")
    o += grid([
        card("اختراق السوق (السنوات 1 إلى 3)", "الخدمات الحالية للشريحة الحالية: شقق وفيلات المجمعات في شرق القاهرة. زيادة نسبة العملاء الذين يسندون الإشراف والتنفيذ."),
        card("تطوير الخدمة (السنوات 2 إلى 4)", "باقات تصميم رقمية مصغرة للوحدات الصغيرة، وخدمة تجهيز الوحدات للإيجار الفندقي، وخط أثاث بالتصنيع لدى الغير."),
        card("تطوير السوق (السنوات 3 إلى 5)", "فريق موسمي للساحل الشمالي، ثم نقطة حضور في الشيخ زايد. تصدير التصميم عن بعد للسعودية والإمارات."),
        card("التنويع (بعد السنة الخامسة)", "شراكات مع مطورين لتصميم الوحدات النموذجية والمناطق المشتركة. لا يُنصح به قبل ترسخ النشاط الأساسي."),
    ], 4)
    o += h2("سلسلة القيمة")
    o += '<div class="flow">' + "".join(f'<div class="step"><b>{a}</b>{b}</div>' for a, b in [("اكتساب العميل", "محتوى، إحالات، شراكات"), ("الاستشارة والتعاقد", "جلسة مدفوعة ثم عرض"), ("التصميم", "مخططات وإظهار واقع افتراضي"), ("التوثيق الفني", "لوحات تنفيذية وكميات"), ("المناقصة", "ثلاثة عروض لكل بند"), ("الإشراف والتنفيذ", "زيارات ومستخلصات"), ("التسليم وما بعده", "ضمان، تصوير، إحالة")]) + '</div>'
    o += p("تتولد القيمة الأعلى في حلقتين: التوثيق الفني الذي يميز المكتب عن المصمم الفرد، والمناقصة الشفافة التي تميزه عن المقاول. الحلقتان هما موضع الاستثمار الأكبر في الكفاءات والأنظمة.")
    return o + end()


def s_marketing():
    leads = [PROJ[0] / .35 / .6 / .25, PROJ[0] / .35 / .6, PROJ[0] / .35, PROJ[0]]
    cac = C['marketing'][0] / PROJ[0]; rpp = R['total'][0] / PROJ[0]
    o = sec(9, "الدراسة التسويقية", "قرار اختيار مصمم داخلي قرار ثقة مرتفع المخاطرة لدى العميل: مبلغ كبير، مرة واحدة، ونتيجة يعيش معها سنوات. لذلك تُبنى الخطة التسويقية على الدليل البصري والإحالة، لا على الإعلان السعري.")
    o += h2("التجزئة والاستهداف والتموضع")
    o += table(["العنصر", "القرار", "المبرر"], [
        ["التجزئة", "حسب نوع الوحدة (شقة، فيلا، تجاري) ومرحلة التسليم (تسلّم خلال 6 أشهر، تسلّم بالفعل، تجديد)", "مرحلة التسليم أقوى مؤشر على جاهزية الشراء"],
        ["الاستهداف", "ملاك الوحدات من 150 إلى 450 م² في مجمعات شرق القاهرة، دخل الأسرة الشهري فوق 150 ألف جنيه، والمكاتب والعيادات من 150 إلى 500 م²", "أعلى تركز للطلب وأقل مسافة للمقر"],
        ["التموضع", "المكتب الذي يريك كل فاتورة: تصميم متقن وتنفيذ بتكلفة معلنة", "يعالج أكبر مخاوف العميل: تجاوز الميزانية وغموض الهوامش"],
    ], "قرارات التجزئة والاستهداف والتموضع", widths=[13, 52, 35])
    o += h2("المزيج التسويقي")
    o += grid([
        card("الخدمة", "تصميم كامل بلوحات تنفيذية، إشراف، إدارة تنفيذ، توريد أثاث. ضمان سنة على الأعمال المنفذة تحت إدارة المكتب."),
        card("السعر", "أتعاب ثابتة للمتر ونسب معلنة للتنفيذ. جلسة استشارية مدفوعة تُخصم من العقد لتصفية غير الجادين."),
        card("المكان", "مقر في التجمع الخامس يعمل كصالة عرض، وجلسات عن بعد للمصريين بالخارج."),
        card("الترويج", "محتوى مصور لمشروعات منفذة، إحالات، شراكات مع وسطاء ومطورين، إعلانات موجهة جغرافياً."),
        card("الأفراد", "مصمم مسؤول واحد لكل عميل من البداية للنهاية، ومهندس إشراف مسمى."),
        card("العمليات", "ثماني مراحل موثقة بمخرجات واعتمادات مكتوبة، وتقرير موقع مصور أسبوعياً."),
        card("الدليل المادي", "مكتبة خامات، عرض بالواقع الافتراضي، ملف تسليم يضم المخططات والضمانات."),
        card("مؤشر النجاح", "نسبة العملاء القادمين بالإحالة 35% في السنة الثالثة.", "nv"),
    ], 4)
    o += h2("قمع المبيعات المطلوب في السنة الأولى")
    o += '<div class="two"><div>' + fig(hbars([("عملاء محتملون مؤهلون", leads[0]), ("جلسات استشارية", leads[1]), ("عروض مقدمة", leads[2]), ("عقود موقعة", leads[3])], w=350, label_w=130, row=30, colors=[MUTE, S1, S1, COPPER]), "قمع المبيعات اللازم لتحقيق مستهدف السنة الأولى", "افتراضات التحويل: 25% من المؤهلين إلى جلسة، 60% من الجلسات إلى عرض، 35% من العروض إلى عقد") + '</div><div>'
    o += p(f"تحقيق {PROJ[0]} عقداً في السنة الأولى يتطلب نحو {num(leads[0])} عميلاً محتملاً مؤهلاً، أي قرابة {num(leads[0] / 12)} شهرياً. بميزانية تسويق {mn(C['marketing'][0], 2)} مليون جنيه تبلغ تكلفة اكتساب العقد نحو {num(cac)} جنيه، مقابل متوسط إيراد للمشروع {num(rpp)} جنيه، أي {pct(cac / rpp, 0)} من الإيراد.")
    o += p("نسبة التحويل من العرض إلى العقد (35%) هي أكثر الافتراضات حساسية. انخفاضها إلى 25% يرفع عدد العملاء المحتملين المطلوب بنحو 40%.") + '</div></div>'
    o += h2("القنوات والميزانية")
    ch = [("محتوى مرئي على إنستغرام وتيك توك وفيسبوك", 30, "جولات مصورة قبل وبعد، مقاطع قصيرة من المواقع"), ("إعلانات رقمية موجهة جغرافياً", 25, "استهداف سكان المجمعات ومتسلمي الوحدات"), ("شراكات المطورين والوسطاء العقاريين", 15, "عمولة إحالة وحضور في فعاليات التسليم"), ("برنامج إحالة العملاء", 10, "رصيد أثاث أو خصم على الصيانة للمُحيل"), ("الموقع الإلكتروني وتحسين الظهور في البحث", 10, "معرض أعمال وحاسبة تكلفة تشطيب"), ("فعاليات ومعارض ورعايات", 10, "معارض الأثاث والعقار ولقاءات اتحادات الملاك")]
    o += table(["القناة", "حصة الميزانية", f"الميزانية في السنة الأولى (جنيه)", "الأنشطة"], [[a, f"{b}%", num(C['marketing'][0] * b / 100), c] for a, b, c in ch] + [{"cls": "tot", "cells": ["الإجمالي", "100%", num(C['marketing'][0]), ""]}], "توزيع ميزانية التسويق على القنوات", widths=[32, 12, 18, 38])
    o += fig(bars(YRS, [("ميزانية التسويق", [v / 1e6 for v in C['marketing']])], unit="مليون جنيه", d=2, h=210), "ميزانية التسويق السنوية", "النموذج المالي للدراسة", f"تمثل {pct(C['marketing'][0] / R['total'][0], 0)} من الإيرادات في السنة الأولى وتنخفض إلى {pct(C['marketing'][4] / R['total'][4], 0)} في الخامسة مع ارتفاع حصة الإحالات.")
    o += h2("رحلة العميل")
    o += '<div class="flow">' + "".join(f'<div class="step"><span class="n">{i + 1}</span><b>{a}</b>{b}<small>{c}</small></div>' for i, (a, b, c) in enumerate([("الاكتشاف", "محتوى أو إحالة", "اليوم 0"), ("التواصل", "رد خلال ساعتين", "اليوم 1"), ("الاستشارة", "جلسة مدفوعة بالمقر", "الأسبوع 1"), ("العرض", "نطاق وسعر وجدول", "الأسبوع 2"), ("التعاقد", "دفعة 40%", "الأسبوع 3"), ("التصميم", "اعتمادان مرحليان", "8 إلى 10 أسابيع"), ("التنفيذ", "تقرير أسبوعي", "4 إلى 6 أشهر"), ("التسليم", "تصوير وطلب إحالة", "النهاية")])) + '</div>'
    o += h2("مؤشرات الأداء التسويقية")
    o += table(["المؤشر", "السنة 1", "السنة 3", "السنة 5"], [["عدد العقود الموقعة", str(PROJ[0]), str(PROJ[2]), str(PROJ[4])], ["نسبة التحويل من العرض إلى العقد", "35%", "40%", "42%"], ["نسبة العملاء القادمين بالإحالة", "10%", "35%", "45%"], ["تكلفة اكتساب العقد (جنيه)", num(cac), num(C['marketing'][2] / PROJ[2]), num(C['marketing'][4] / PROJ[4])], ["نسبة إسناد الإشراف أو التنفيذ", "45%", "60%", "65%"], ["صافي نقاط الترويج (NPS)", "50", "60", "65"]], "مؤشرات الأداء التسويقية المستهدفة", cls="numt", widths=[46, 18, 18, 18])
    return o + end()


def s_org():
    o = sec(10, "الدراسة التنظيمية والقانونية", "يحدد هذا القسم الشكل القانوني والتراخيص والهيكل التنظيمي وخطة القوى العاملة والحوكمة.")
    o += h2("الشكل القانوني")
    o += p("نوصي بتأسيس شركة ذات مسؤولية محدودة وفق قانون الشركات رقم 159 لسنة 1981 عبر الهيئة العامة للاستثمار والمناطق الحرة. يحصر هذا الشكل مسؤولية الشركاء في حصصهم، ويسمح بدخول شريك ممول لاحقاً، ولا يشترط حداً أدنى مرتفعاً لرأس المال. يُسجَّل النشاط باسم: التصميم الداخلي والاستشارات الهندسية وإدارة مشروعات التشطيب والتوريدات.")
    o += table(["الإجراء", "الجهة", "المدة التقديرية", "ملاحظات"], [
        ["تأسيس الشركة والسجل التجاري", "الهيئة العامة للاستثمار", "أسبوع إلى أسبوعين", "عقد تأسيس ونظام أساسي وشهادة إيداع رأس المال"],
        ["البطاقة الضريبية والتسجيل الإلكتروني", "مصلحة الضرائب المصرية", "أسبوع", "الانضمام لمنظومة الفاتورة الإلكترونية"],
        ["التسجيل في ضريبة القيمة المضافة", "مصلحة الضرائب المصرية", "أسبوع", "الخدمات المهنية والاستشارية تخضع لضريبة جدول 10%"],
        ["التأمينات الاجتماعية", "الهيئة القومية للتأمين الاجتماعي", "أسبوع", "وفق قانون 148 لسنة 2019"],
        ["القيد المهني", "نقابة المهندسين أو نقابة مصممي الفنون التطبيقية", "2 إلى 4 أسابيع", "قيد المدير الفني وسجل المكاتب الاستشارية عند الحاجة"],
        ["رخصة مزاولة النشاط للمقر", "جهاز مدينة القاهرة الجديدة", "2 إلى 4 أسابيع", "تتطلب عقد إيجار موثقاً لوحدة إدارية"],
    ], "الإجراءات القانونية والتراخيص", "تجميع فريق الدراسة، ويُراجع مع المستشار القانوني قبل التأسيس", widths=[27, 25, 16, 32])
    o += callout("المعاملة الضريبية", "احتسبت الدراسة ضريبة الدخل بالسعر العام 22.5% على صافي الربح، مع ترحيل الخسائر. قد يستفيد المشروع من النظام الضريبي المبسط للمشروعات التي لا تتجاوز إيراداتها السنوية 20 مليون جنيه وفق القانون رقم 6 لسنة 2025، وهو ما يحسّن النتائج في السنتين الأوليين. لم نُدخل هذه الميزة في الحالة الأساسية التزاماً بالتحفظ.")
    o += h2("الهيكل التنظيمي")
    o += '''<div class="org"><div class="row"><div class="box top">المدير العام والمدير الإبداعي<small>شريك مؤسس</small></div></div>
<div class="row"><div class="box mid">إدارة التصميم<small>مدير تصميم</small></div><div class="box mid">إدارة التنفيذ<small>مدير مشروعات (من السنة 2)</small></div><div class="box mid">تطوير الأعمال والتسويق</div><div class="box mid">المالية والإدارة</div></div>
<div class="row" style="margin-bottom:0"><div class="box">مصممون داخليون</div><div class="box">مصممو إظهار</div><div class="box">المكتب الفني</div><div class="box">مهندسو الإشراف</div><div class="box">الحصر والمشتريات</div><div class="box">علاقات العملاء</div><div class="box">التسويق الرقمي</div><div class="box">محاسب وإداري</div></div></div>'''
    o += '<div class="src" style="text-align:center">شكل توضيحي للهيكل التنظيمي في السنة الثالثة. المصدر: فريق الدراسة</div>'
    o += h2("خطة القوى العاملة")
    rows = [[n, num(s)] + [str(h) for h in hc] for n, s, hc, _ in ROLES]
    rows.append({"cls": "tot", "cells": ["إجمالي عدد العاملين", ""] + [f"{h:.0f}" for h in M['head']]})
    rows.append({"cls": "sub", "cells": ["تكلفة الأجور السنوية شاملة الأعباء (مليون جنيه)", ""] + [mn(v) for v in C['payroll']]})
