    o += fig(bars(YRS, [("الطاقة التصميمية", cap), ("المشروعات المستهدفة", PROJ)], d=0, unit="مشروع سنوياً", h=230, legend_gap=110), "الطاقة التصميمية مقابل المشروعات المستهدفة")
    o += h2("الجدول الزمني للتأسيس والافتتاح")
    tasks = [("تأسيس الشركة والتراخيص", 1, 2), ("إغلاق التمويل", 1, 2), ("التعاقد على المقر", 2, 2), ("تصميم وتجهيز المقر", 3, 5), ("شراء الأجهزة والبرمجيات", 4, 5), ("التوظيف والتدريب", 3, 6), ("الهوية والموقع والمحتوى", 2, 5), ("ثلاثة مشروعات نموذجية", 4, 6), ("حملة الإطلاق", 5, 6)]
    hdr = ["النشاط"] + [f"ش{i}" for i in range(1, 7)]
