def s_risk():
    risks = [("تأخر اكتساب العملاء في السنة الأولى", 4, 4, "مشروعات نموذجية قبل الافتتاح، شراكات تحويل، احتياطي سيولة 6 أشهر"), ("انخفاض نسبة إسناد إدارة التنفيذ", 3, 5, "باقة سعرية تحفز الإسناد، إثبات الوفر بمقارنة العروض"), ("فقدان كفاءات أساسية", 3, 4, "مشاركة في الأرباح، توثيق العمليات، مصمم بديل لكل مشروع"), ("تضخم الرواتب فوق المتوقع", 4, 3, "ربط الزيادات بالإنتاجية، مراجعة الأسعار كل ستة أشهر"), ("تباطؤ تسليم الوحدات العقارية", 3, 3, "تنويع نحو التجديد والتجاري"), ("نزاعات مع العملاء حول التنفيذ", 3, 3, "عقود واضحة النطاق، اعتمادات مكتوبة، تأمين مسؤولية مهنية"), ("تعثر مقاول أثناء التنفيذ", 2, 4, "قائمة معتمدة، ضمان أعمال، دفعات مرتبطة بالإنجاز"), ("انخفاض الجنيه وارتفاع تكلفة البرمجيات", 4, 2, "بند صغير نسبياً، إيرادات تصدير بالعملة الصعبة لاحقاً"), ("منافسة أدوات الذكاء الاصطناعي", 3, 2, "توظيفها داخلياً والتركيز على التوثيق والإشراف"), ("ارتفاع إضافي في أسعار الفائدة", 2, 3, "نسبة دين 35% فقط، سداد معجل عند توفر فائض")]
    o = sec(14, "تحليل المخاطر وخطة التخفيف", "حُددت عشرة مخاطر رئيسية وقُيّمت باحتمال الحدوث وشدة الأثر على مقياس من 1 إلى 5، ورُبط كل خطر بإجراء تخفيف ومسؤول عنه.")
