    o += h2("بطاقة التقييم المرجحة")
    o += table(["المعيار", "الوزن", "الدرجة من 5", "الدليل"], [[a, f"{w}%", f"{s:.1f}", e] for a, w, s, e in crit] + [{"cls": "tot", "cells": ["الدرجة المرجحة", "100%", f"{score:.2f}", "4 فأعلى: قوية. من 3 إلى أقل من 4: جيدة بشروط. أقل من 3: ضعيفة"]}], "بطاقة تقييم الفرصة الاستثمارية", widths=[27, 9, 12, 52])
    o += fig(hbars([(a, s) for a, _, s, _ in crit], vmax=5.6, d=1, label_w=215, row=28, colors=[GOOD if s >= 4 else S1 if s >= 3 else WARN for _, _, s, _ in crit]), "درجات معايير التقييم", "تقييم فريق الدراسة", "الأخضر: 4 فأعلى. الأزرق: من 3 إلى أقل من 4. الأصفر: أقل من 3.")
    o += h2("اختبارات القبول الكمية")
